kit.score(function (S, T) {
  // A slow three: 80 beats a minute, so each scene is two bars and every cut lands on a downbeat.
  const B = 60 / 80;
  S.tempo(80, { t0: 0 });
  S.program('pad', 'pad', { rev: 0.7, gain: -4 }); S.program('bass', 'bass', { gain: -6 }); S.program('bells', 'glock', { rev: 0.6, gain: -5 }); S.program('wood', 'marimba', { rev: 0.4, gain: -3 });
  // Night: one held chord, and three notes climbing with the sun.
  S.chord('pad', ['D3', 'A3', 'F#4'], { t: 0, dur: 4.5, vel: 34 });
  S.run('bells', ['A4', 'D5', 'F#5'], { t: 1.5, step: 2 * B / 2, vel: 40, cresc: 14 });
  // The pour: the waltz comes in under the stream.
  S.chord('pad', ['G3', 'D4', 'B4'], { t: T.pour, dur: 4.5, vel: 44 });
  S.note('bass', 'G2', { t: T.pour, dur: 2.2, vel: 56 }); S.note('bass', 'G2', { t: T.pour + 3 * B, dur: 2.2, vel: 52 });
  S.pattern('wood', 'X.x.x.', { from: T.pour / B, repeat: 2, pitch: ['B4', 'D5', 'G5'], vel: 54 });
  S.fx('whoosh', T.pour + 0.5, { dur: 0.5, vel: 30 });
  // The notes: one bell for each as it lands.
  S.chord('pad', ['A3', 'E4', 'C#5'], { t: T.notes, dur: 4.5, vel: 46 });
  S.note('bass', 'A2', { t: T.notes, dur: 2.2, vel: 56 }); S.note('bass', 'A2', { t: T.notes + 3 * B, dur: 2.2, vel: 54 });
  [['D5', 0.15], ['F#5', 0.9], ['A5', 1.65]].forEach(([pitch, at]) => { S.note('bells', pitch, { t: T.notes + at, dur: 1.2, vel: 66 }); S.fx('pop', T.notes + at, { vel: 48 }); });
  S.pattern('wood', 'x.x.x.', { from: T.notes / B + 3, repeat: 1, pitch: ['A4', 'C#5', 'E5'], vel: 50 });
  // Morning: the card lands on the home chord, and it rings.
  S.chord('pad', ['D3', 'A3', 'D4', 'F#4'], { t: T.end, dur: 4.5, vel: 62 });
  S.note('bass', 'D2', { t: T.end, dur: 4, vel: 68 });
  S.chord('bells', ['D5', 'A5'], { t: T.end + 0.3, dur: 2.5, vel: 72 });
  S.fx('chime', T.end + 1.2, { vel: 58 });
  S.run('wood', ['F#4', 'A4', 'D5', 'F#5'], { t: T.end + 1.5, step: B / 2, vel: 48 });
  S.master({ gain: -6, fadeOut: 1.4 });
});
